style.css:
/* ChatGPT glass neon theme */

:root {
  --bg: #09090f;
  --panel: rgba(20, 22, 35, 0.72);
  --text: #f4f7ff;
  --muted: #a7b0c5;
  --accent: #8b5cf6;
  --accent2: #22d3ee;
}

/* фон */
body {
  background:
    radial-gradient(circle at top left, rgba(139,92,246,.35), transparent 30%),
    radial-gradient(circle at bottom right, rgba(34,211,238,.22), transparent 35%),
    var(--bg) !important;
  color: var(--text) !important;
}

/* основной контейнер */
main,
[class*="composer"],
[class*="thread"] {
  background: transparent !important;
}

/* сообщения */
[data-message-author-role] {
  border-radius: 20px !important;
  margin: 14px auto !important;
}

[data-message-author-role="assistant"] {
  background: var(--panel) !important;
  backdrop-filter: blur(18px);
  border: 1px solid rgba(139,92,246,.25);
  box-shadow: 0 0 30px rgba(139,92,246,.12);
  padding: 18px !important;
}

[data-message-author-role="user"] {
  background: linear-gradient(135deg, rgba(139,92,246,.35), rgba(34,211,238,.18)) !important;
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: 0 0 24px rgba(34,211,238,.10);
  padding: 18px !important;
}

/* поле ввода */
form textarea,
[contenteditable="true"] {
  color: var(--text) !important;
}

form,
[class*="composer"] {
  background: rgba(15, 17, 28, .78) !important;
  backdrop-filter: blur(22px);
  border: 1px solid rgba(255,255,255,.12) !important;
  border-radius: 24px !important;
  box-shadow: 0 0 40px rgba(139,92,246,.16);
}

/* кнопки */
button {
  border-radius: 14px !important;
}

button:hover {
  box-shadow: 0 0 18px rgba(34,211,238,.35) !important;
}

/* ссылки */
a {
  color: var(--accent2) !important;
}

/* код */
pre,
code {
  background: rgba(0,0,0,.38) !important;
  border-radius: 14px !important;
  border: 1px solid rgba(139,92,246,.25);
}

/* сайдбар */
nav,
aside {
  background: rgba(8, 9, 15, .82) !important;
  backdrop-filter: blur(18px);
  border-right: 1px solid rgba(255,255,255,.08);
}
